"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

Post-hoc control for the time-resolved ears diagnostic (added 2026-11-20 AFTER seeing its results; not part of the
logged design). Probes only, train and dev only; no training of systems, no API.

The per-second pooling (sec8: mean and max of each of the 8 seconds, 16,384 numbers) lifted the S-move group all-right
from 0.58 to 0.82, while the three-segment pooling (seg3, the logged primary) did not move. Is the gain about time
(which second a sound falls in) or about the larger feature set? Same probe as scripts/p1v4_ears_time_diag.py, on the
same per-second features with the seconds permuted at random per window (seed 0; one permutation per window, shared
by its mean and max):
- sec8 shuffled: all 8 seconds permuted (keeps the size and every second's content, removes position);
- sec8 last kept: the last second (the door or cupboard sound, 1 s before the decision point) kept in place, the first
  7 seconds permuted (removes where the bell and the footsteps fall).
Output: results/main_v04/ears_time_control_dev.json
usage (repo root): .venv-gpu/Scripts/python.exe -X utf8 scripts/p1v4_ears_time_control.py
"""
import json
import os
import sys
import time

import numpy as np

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import p1v4_ears_time_diag as ET  # noqa: E402
import p1v4_grounding as G  # noqa: E402
import p1v4_grounding_report as GR  # noqa: E402


def permute(sm, sx, keep_last, rng):
    n = len(sm)
    k = 7 if keep_last else 8
    perm = np.argsort(rng.random((n, k)), 1)
    if keep_last:
        perm = np.concatenate([perm, np.full((n, 1), 7)], 1)
    rows = np.arange(n)[:, None]
    return sm[rows, perm], sx[rows, perm]


def main():
    from sklearn.linear_model import LogisticRegression
    tr = np.load(f"{ET.OUT}/feats_train.npz")
    dv = np.load(f"{ET.OUT}/feats_dev.npz")
    drow = {i: n for n, i in enumerate(dv["ids"])}
    rows, _ = G.load("dev")
    groups = G.load_groups("dev")
    cl = GR.cluster_table(rows, "dev")
    diag = json.load(open(ET.RES))
    res = {"note": "post hoc, added after seeing the diagnostic", "parts": {}}
    for part, task in ET.TASK.items():
        m = (tr["parts"] == part) & (tr["y"] >= 0)
        sm_tr, sx_tr, y = tr["sec_mean"][m].astype(np.float32), tr["sec_max"][m].astype(np.float32), tr["y"][m]
        gs = [g for g in groups if g["part"] == part]
        units = [g["unit"] for g in gs]
        vers = diag["parts"][part]["versions"]
        flat = [drow[f"{g['unit']}|{v}|{g['k']}"] for g in gs for v in vers]
        sm_dv, sx_dv = dv["sec_mean"][flat].astype(np.float32), dv["sec_max"][flat].astype(np.float32)
        ev = 1 if task == "S" else 0
        v1 = vers.index("1")
        others = [j for j in range(len(vers)) if j != v1]
        out = {}
        for name, keep_last in (("sec8 shuffled", False), ("sec8 last kept", True)):
            rng = np.random.default_rng(0)
            a_tr = ET.pool(*permute(sm_tr, sx_tr, keep_last, rng), "sec8")
            a_dv = ET.pool(*permute(sm_dv, sx_dv, keep_last, rng), "sec8")
            mu, sd = a_tr.mean(0), a_tr.std(0) + 1e-6
            t0 = time.time()
            clf = LogisticRegression(C=0.1, max_iter=2000).fit((a_tr - mu) / sd, y)
            p1 = clf.predict_proba((a_dv - mu) / sd)[:, 1]
            sc = (p1 if ev == 1 else 1 - p1).reshape(len(gs), len(vers))
            r = ((sc[:, v1] >= 0.5) & np.all(sc[:, others] < 0.5, 1)).astype(float)
            c = GR.criterion(units, cl, {}, lambda w, a=r: GR.wmean(w, a), lambda a=r: float(a.mean()))
            out[name] = {"group_all_right_0.5": c["point"], "ci95": c["ci95"],
                         "auc_v1_vs_others": ET.auc(sc[:, v1], sc[:, others].ravel()),
                         "hit_v1_0.5": float(np.mean(sc[:, v1] >= 0.5)),
                         "false_alarm_0.5": {vers[j]: float(np.mean(sc[:, j] >= 0.5)) for j in others},
                         "fit_s": round(time.time() - t0, 1)}
            print(f"{part} {name:15s} all-right {c['point']:.3f} [{c['ci95'][0]:.3f}, {c['ci95'][1]:.3f}] AUC "
                  f"{out[name]['auc_v1_vs_others']:.3f} hit {out[name]['hit_v1_0.5']:.3f} fa "
                  f"{json.dumps({k: round(v, 3) for k, v in out[name]['false_alarm_0.5'].items()})}", flush=True)
        out["for reference (diagnostic)"] = {k: diag["parts"][part]["poolings"][k]["group_all_right_0.5"]
                                             for k in ET.POOLINGS}
        res["parts"][part] = out
    json.dump(res, open("results/main_v04/ears_time_control_dev.json", "w"), indent=1)


if __name__ == "__main__":
    main()
